def binary_search(sentence, target):
    left = 0
    right = len(sentence)
    while left < right:
        mid = (left + right) // 2
        if sentence[mid] == target:
            return mid
        elif sentence[mid] < target:
            left = mid + 1
        else:
            right = mid
    return -1

